import{_ as o,a0 as p,w as d,s as r,ao as n,I as l,x as i,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"SSH 密鑰管理工具 | LCTT x X-CMD","titleTemplate":false,"description":"SSH 密鑰管理工具 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SSH 密鑰管理工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SSH 密鑰管理工具 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200220 Tools for SSH key management","title":"SSH 密鑰管理工具","tag":"202003","desc":""},"relativePath":"202003/20200220 Tools for SSH key management.md","filePath":"[post].md"}'),h={name:"202003/20200220 Tools for SSH key management.md"};function g(k,s,u,b,m,c){const t=p("Link");return d(),r("div",null,[s[20]||(s[20]=n('<h1 id="ssh-密鑰管理工具" tabindex="-1">SSH 密鑰管理工具 <a class="header-anchor" href="#ssh-密鑰管理工具" aria-label="Permalink to “SSH 密鑰管理工具”">​</a></h1><blockquote><p>常用開源工具的省時快捷方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/01/122336zyldgpse6eyrbymt.jpg" alt=""></p><p>我經常使用 SSH。我發現自己每天都要登錄多個服務器和樹莓派（與我位於同一房間，並接入互聯網）。我有許多設備需要訪問，並且獲得訪問權限的要求也不同，因此，除了使用各種 <code>ssh</code> / <code>scp</code> 命令選項之外，我還必須維護一個包含所有連接詳細信息的配置文件。</p><p>隨着時間的推移，我發現了一些省時的技巧和工具，你可能也會發現它們有用。</p><h3 id="ssh-密鑰" tabindex="-1">SSH 密鑰 <a class="header-anchor" href="#ssh-密鑰" aria-label="Permalink to “SSH 密鑰”">​</a></h3><p>SSH 密鑰是一種在不使用密碼的情況下認證 SSH 連接的方法，可以用來加快訪問速度或作為一種安全措施（如果你關閉了密碼訪問權限並確保僅允許授權的密鑰）。要創建 SSH 密鑰，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-keygen</span></span></code></pre></div><p>這將在 <code>~/.ssh/</code> 中創建一個密鑰對（公鑰和私鑰）。將私鑰（<code>id_rsa</code>）保留在 PC 上，切勿共享。你可以與其他人共享公鑰（<code>id_rsa.pub</code>）或將其放置在其他服務器上。</p><h3 id="ssh-copy-id" tabindex="-1">ssh-copy-id <a class="header-anchor" href="#ssh-copy-id" aria-label="Permalink to “ssh-copy-id”">​</a></h3><p>如果我在家中或公司工作時使用樹莓派，則傾向於將 SSH 設置保留為默認設置，因為我不擔心內部信任網絡上的安全性，並且通常將 SSH 密鑰（公鑰）複製到樹莓派上，以避免每次都使用密碼進行身份驗證。為此，我使用 <code>ssh-copy-id</code> 命令將其複製到樹莓派。這會自動將你的密鑰（公鑰）添加到樹莓派：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-copy-id pi@192.168.1.20</span></span></code></pre></div><p>在生產服務器上，我傾向於關閉密碼身份驗證，僅允許授權的 SSH 密鑰登錄。</p><h3 id="ssh-import-id" tabindex="-1">ssh-import-id <a class="header-anchor" href="#ssh-import-id" aria-label="Permalink to “ssh-import-id”">​</a></h3><p>另一個類似的工具是 <code>ssh-import-id</code>。你可以使用此方法通過從 GitHub 導入密鑰來授予你自己（或其他人）對計算機或服務器的訪問權限。例如，我已經在我的 GitHub 帳户中註冊了各個 SSH 密鑰，因此無需密碼即可推送到 GitHub。這些公鑰是有效的，因此 <code>ssh-import-id</code> 可以使用它們在我的任何計算機上授權我：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-import-id gh:bennuttall</span></span></code></pre></div><p>我還可以使用它來授予其他人訪問服務器的權限，而無需詢問他們的密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-import-id gh:waveform80</span></span></code></pre></div><h3 id="storm" tabindex="-1">storm <a class="header-anchor" href="#storm" aria-label="Permalink to “storm”">​</a></h3><p>我還使用了名為 Storm 的工具，該工具可幫助你將 SSH 連接添加到 SSH 配置中，因此你不必記住這些連接細節信息。你可以使用 <code>pip</code> 安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pip3 install stormssh</span></span></code></pre></div><p>然後，你可以使用以下命令將 SSH 連接信息添加到配置中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ storm add pi3 pi@192.168.1.20</span></span></code></pre></div><p>然後，你可以只使用 <code>ssh pi3</code> 來獲得訪問權限。類似的還有 <code>scp file.txt pi3:</code> 或 <code>sshfs pi pi3:</code>。</p><p>你還可以使用更多的 SSH 選項，例如端口號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ storm add pi3 pi@192.168.1.20:2000</span></span></code></pre></div>',26)),l("p",null,[s[1]||(s[1]=i("你可以參考 Storm 的",-1)),e(t,{href:"https://stormssh.readthedocs.io/en/stable/usage.html"},{default:a(()=>[...s[0]||(s[0]=[i("文檔",-1)])]),_:1}),s[2]||(s[2]=i("輕鬆列出、搜索和編輯已保存的連接。Storm 實際所做的只是管理 SSH 配置文件 ",-1)),s[3]||(s[3]=l("code",null,"~/.ssh/config",-1)),s[4]||(s[4]=i(" 中的項目。一旦瞭解了它們是如何存儲的，你就可以選擇手動編輯它們。配置中的示例連接如下所示：",-1))]),s[21]||(s[21]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host pi3</span></span>
<span class="line"><span>   user pi</span></span>
<span class="line"><span>   hostname 192.168.1.20</span></span>
<span class="line"><span>   port 22</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>從樹莓派到大型的雲基礎設施，SSH 是系統管理的重要工具。熟悉密鑰管理會很方便。你還有其他 SSH 技巧要添加嗎？我希望你在評論中分享他們。</p><hr>`,4)),l("p",null,[s[6]||(s[6]=i("via: ",-1)),e(t,{href:"https://opensource.com/article/20/2/ssh-tools"},{default:a(()=>[...s[5]||(s[5]=[i("https://opensource.com/article/20/2/ssh-tools",-1)])]),_:1})]),l("p",null,[s[11]||(s[11]=i("作者：",-1)),e(t,{href:"https://opensource.com/users/bennuttall"},{default:a(()=>[...s[7]||(s[7]=[i("Ben Nuttall",-1)])]),_:1}),s[12]||(s[12]=i(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[8]||(s[8]=[i("lujun9972",-1)])]),_:1}),s[13]||(s[13]=i(" 譯者：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1}),s[14]||(s[14]=i(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[10]||(s[10]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[17]||(s[17]=i("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[15]||(s[15]=[i("LCTT",-1)])]),_:1}),s[18]||(s[18]=i(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...s[16]||(s[16]=[i("Linux中國",-1)])]),_:1}),s[19]||(s[19]=i(" 榮譽推出",-1))])])}const C=o(h,[["render",g]]);export{y as __pageData,C as default};
